<?php use function KB\{e,url}; ?><section class="page-heading"><div><span class="eyebrow">ACCOUNTABILITY, BUILT IN</span><h1>A clear record of care.</h1><p>Security and administrative events. Passwords, access tokens and SMTP secrets are never recorded here.</p></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Activity</th><th>Actor</th><th>Subject</th><th>Time (UTC)</th></tr></thead><tbody><?php foreach($events as $event): ?><tr><td><strong><?= e(ucfirst(str_replace(['.','_'],' ',$event['action']))) ?></strong><?php if($event['admin_id']): ?><small>Administrator support action</small><?php endif; ?></td><td><?= e($event['name']??'System / removed account') ?></td><td><?= e($event['subject_type'].' #'.$event['subject_id']) ?></td><td><?= e($event['created_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php require __DIR__.'/../pagination.php'; ?></section>
